                font-size: 2rem;
            }

            .hero-content p {
                font-size: 1rem;
            }

            .match-card {
                flex-direction: column;
                gap: 1rem;
                text-align: center;
            }

            .match-teams {
                flex-direction: column;
                gap: 1rem;
            }

            .match-score {
                font-size: 2rem;
            }
        }
    </style>
